"""Write synthetic/<letter>/README.md: one paragraph on the variation and a table of derived dates per case."""
import json, os
from cal import d, fmt, is_bd
from derive import HOL, deadline, floor, attempt_dates
from validate import FULL_FIELD, TYPE_FIELD

ROOT = os.path.join(os.path.dirname(__file__), "..")

