def main():
    for b in "CDEFGHIJ":
        cases = json.load(open(os.path.join(ROOT, b, "cases.json")))
        h = HOL[b]
        rows = ["| Case | `now` | Product | Deadline | Floor | Expected |", "|---|---|---|---|---|---|"]
        for c in cases:
            today = d(c["variables"]["now"])
            e = c["expected"]
            for i, p in enumerate(c["products"], 1):
                pid = f"p{i}"
                dl = deadline(b, today, p)
                fl = floor(b, p)
                exp = []
                for pr in e["promises"]:
                    if pr["product_id"] == pid:
                        exp.append(f"promise {pr['amount']} on {fmt(d(pr['date']))}")
                for n in e["notes"]:
                    if n["product_id"] == pid:
                        exp.append(f"note {n['reason']}")
                if i == 1:
                    for cb in e["callbacks"]:
                        exp.append(f"callback {fmt(d(cb['date']))} {cb['time']}")
                    for t in e["transfers"]:
                        exp.append(f"transfer {t['queue']}")
                    exp.append(f"close {e['outcome']}" + (f" / {e['reason']}" if e["reason"] else ""))
                att = attempt_dates(b, today, dl)
                rows.append(f"| {c['id']} | {fmt(today)} {c['variables']['now'][11:]} | {pid} {p[TYPE_FIELD[b]]} {p[FULL_FIELD[b]]}, {p.get('days_late', p.get('days_overdue', p.get('days_in_arrears')))} d | {fmt(dl)} | {fl} | {'; '.join(exp)} |")
        styles = ", ".join(f"{c['id']} {c['style']}" for c in cases if c.get("style"))
        text = f"# Brief {b}: what it varies and the derived dates\n\n{PARA[b]}\n\n## Derived dates per case\n\nDeadline and floor re-derived from the brief's own rules and calendar by `_tools/derive.py`; every value was also computed by hand before the script was written (see the per-case `checks`). Harness convention: the brief's id variable (`client_ref`, `customer_id`, `customer_ref` or `account_no`) is generated per call and injected into every tool body; products get `product_id` `p1`, `p2`, `p3` in the order of the `products` list, which is the order `get_account` returns them.\n\n" + "\n".join(rows) + f"\n\nTalking styles: {styles}.\n"
        with open(os.path.join(ROOT, b, "README.md"), "w") as f:
            f.write(text)
        print("wrote", b)


if __name__ == "__main__":
    main()
